import{_ as t,o,c as a,a0 as n}from"./chunks/framework.BxrwG5q5.js";const h=JSON.parse('{"title":"Segments","description":"","frontmatter":{},"headers":[],"relativePath":"features/segments.md","filePath":"features/segments.md"}'),i={name:"features/segments.md"};function r(s,e,d,c,l,u){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="segments" tabindex="-1">Segments <a class="header-anchor" href="#segments" aria-label="Permalink to &quot;Segments&quot;">​</a></h1><blockquote><p>See also: <a href="/config/features/targeting.html">Targeting Rules</a> · <a href="/config/guide/scopes.html">Configuration Scopes</a> · <a href="/config/features/rollouts.html">Percentage Rollouts</a></p></blockquote><p>Segments are reusable <strong>audience segments</strong> — named cohorts of users defined by conditions on context attributes. Define a cohort once (&quot;Enterprise Users&quot;, &quot;Beta Testers&quot;, &quot;Mobile users in the EU&quot;) and reference it across every flag, rather than duplicating conditions everywhere.</p><p>See <a href="/config/guide/scopes.html">Configuration Scopes</a> for how segments fit into the broader evaluation model.</p><h2 id="creating-a-segment" tabindex="-1">Creating a Segment <a class="header-anchor" href="#creating-a-segment" aria-label="Permalink to &quot;Creating a Segment&quot;">​</a></h2><ol><li>Go to <strong>Segments</strong> in the portal</li><li>Click <strong>Create Segment</strong></li><li>Name it (name your cohort clearly — it will appear in every targeting rule)</li><li>Define conditions using attributes</li></ol><h2 id="condition-logic-—-dnf" tabindex="-1">Condition Logic — DNF <a class="header-anchor" href="#condition-logic-—-dnf" aria-label="Permalink to &quot;Condition Logic — DNF&quot;">​</a></h2><p>Segments use <strong>DNF (Disjunctive Normal Form)</strong>:</p><ul><li>Conditions within a group are <strong>AND</strong> (all must match)</li><li>Groups are <strong>OR</strong> (any matching group is sufficient)</li></ul><p><strong>Example:</strong> &quot;Enterprise users in US/UK, OR anyone with a @company.com email&quot;</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Group 1: plan equals &quot;enterprise&quot; AND country in_list &quot;US,UK&quot;</span></span>
<span class="line"><span>   OR</span></span>
<span class="line"><span>Group 2: email ends_with &quot;@company.com&quot;</span></span></code></pre></div><h2 id="using-segments-in-targeting" tabindex="-1">Using Segments in Targeting <a class="header-anchor" href="#using-segments-in-targeting" aria-label="Permalink to &quot;Using Segments in Targeting&quot;">​</a></h2><ol><li>Open a config → click <strong>Target Segment</strong></li><li>Select one or more segment badges</li><li>Set the value to serve for users in those segments</li><li>Multiple segments use OR logic — user in ANY selected segment gets the value</li></ol><h2 id="supported-operators" tabindex="-1">Supported Operators <a class="header-anchor" href="#supported-operators" aria-label="Permalink to &quot;Supported Operators&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operator</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>equals</code></td><td>Exact match</td><td><code>plan</code> equals <code>&quot;pro&quot;</code></td></tr><tr><td><code>not_equals</code></td><td>Does not match</td><td><code>status</code> not_equals <code>&quot;banned&quot;</code></td></tr><tr><td><code>contains</code></td><td>Substring</td><td><code>email</code> contains <code>&quot;@gmail&quot;</code></td></tr><tr><td><code>starts_with</code></td><td>Prefix</td><td><code>user_id</code> starts_with <code>&quot;usr_&quot;</code></td></tr><tr><td><code>ends_with</code></td><td>Suffix</td><td><code>email</code> ends_with <code>&quot;.edu&quot;</code></td></tr><tr><td><code>in_list</code></td><td>Any in comma-separated list</td><td><code>country</code> in_list <code>&quot;US,UK,DE&quot;</code></td></tr><tr><td><code>not_in_list</code></td><td>None in list</td><td><code>plan</code> not_in_list <code>&quot;free,trial&quot;</code></td></tr><tr><td><code>greater_than</code></td><td>Numeric greater</td><td><code>age</code> greater_than <code>18</code></td></tr><tr><td><code>less_than</code></td><td>Numeric less</td><td><code>login_count</code> less_than <code>5</code></td></tr><tr><td><code>regex_match</code></td><td>Regular expression</td><td><code>email</code> regex_match <code>&quot;.*@corp\\\\.com$&quot;</code></td></tr></tbody></table><h2 id="segment-usage-tracking" tabindex="-1">Segment Usage Tracking <a class="header-anchor" href="#segment-usage-tracking" aria-label="Permalink to &quot;Segment Usage Tracking&quot;">​</a></h2><p>The portal shows which configs reference each segment — understand the blast radius before modifying or deleting a cohort definition.</p><h2 id="security-model" tabindex="-1">Security Model <a class="header-anchor" href="#security-model" aria-label="Permalink to &quot;Security Model&quot;">​</a></h2><ul><li><strong>Client keys (<code>cid_</code>):</strong> Segment conditions are evaluated server-side. Your cohort definitions never reach the browser.</li><li><strong>Server keys (<code>svr_</code>):</strong> Segment definitions are included in the API response for local SDK evaluation.</li></ul><h2 id="auto-context-attributes" tabindex="-1">Auto-Context Attributes <a class="header-anchor" href="#auto-context-attributes" aria-label="Permalink to &quot;Auto-Context Attributes&quot;">​</a></h2><p><code>autoContext()</code> detects browser, OS, device, locale, and timezone automatically — available as segment conditions without any extra configuration. Create a &quot;Mobile Users&quot; segment with <code>device equals &quot;mobile&quot;</code> and it works out of the box.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/config/features/targeting.html">Targeting Rules</a> — Use segments in targeting for A/B testing and feature gating</li><li><a href="/config/features/rollouts.html">Percentage Rollouts</a> — Combine segments with rollouts for ring deployments (canary to internal cohort first)</li><li><a href="/config/guide/scopes.html">Configuration Scopes</a> — How context, segments, and evaluation interact</li><li><a href="/config/features/export.html">Export</a> — Bulk export includes segment definitions</li></ul>`,23)])])}const m=t(i,[["render",r]]);export{h as __pageData,m as default};
